// Support routines for the generated FFI shim.
//
// Everything in this file is hand written; the per-class translation units are
// generated by `vtk-gen`.

#include "rvtk_shim.h"

#include <cstdlib>
#include <cstring>

#include <vtkObjectBase.h>

extern "C" void rvtk_register(void* obj)
{
  if (obj)
  {
    static_cast<vtkObjectBase*>(obj)->Register(nullptr);
  }
}

extern "C" void rvtk_delete(void* obj)
{
  if (obj)
  {
    static_cast<vtkObjectBase*>(obj)->Delete();
  }
}

extern "C" char* rvtk_strdup(const char* s)
{
  if (!s)
  {
    return nullptr;
  }
  const std::size_t n = std::strlen(s);
  auto* p = static_cast<char*>(std::malloc(n + 1));
  if (p)
  {
    std::memcpy(p, s, n + 1);
  }
  return p;
}

extern "C" void rvtk_free(void* p)
{
  std::free(p);
}
